stimativa do total."},"detalhes":["Cerca de 20 peças","Sushi, niguiri e uramaki","Sem molhos cremosos","Refrigerante zero"],"tags":["japonesa","combo"]},{"id":"restaurante-japones-ocasional","titulo":"Combinado grande, 24 peças","descricao":"Maioria sushi, sashimi e uramaki tradicional, com 4 hot rolls. Sem tempura, molho especial moderado. Com refrigerante zero.","nivel":"ocasional","energia":{"kcal":1050,"mostrarKcal":true,"observacao":"Estimativa do total."},"detalhes":["24 peças","4 hot rolls","Sem tempura","Molho especial moderado","Refrigerante zero"],"tags":["japonesa","combo"]}],"observacoes":["Restaurante japonês não tem tabela publicada, então estes números são estimativa. Use como ordem de grandeza, não como medida.","Molho shoyu tradicional ou light.","O salmão é um peixe muito saudável, mas é rico em gordura, o que eleva o valor calórico da refeição. Para reduzir, prefira atum, peixe branco ou camarão."]}],"lembretes":[],"logo":null}'::jsonb, array['japonesa', 'japones', 'sushi', 'sashimi', 'rodizio', 'temaki']::text[]) on conflict (id) do update set titulo = excluded.titulo, resumo = excluded.resumo, icone = excluded.icone, ordem = excluded.ordem, status = excluded.status, corpo = excluded.corpo, tags = excluded.tags, atualizado_em = now();
insert into conteudos (id, tipo, titulo, tema, resumo, icone, ordem, status, corpo, tags) values ('massas', 'comer_fora', 'Massas', null, 'Quantidade da massa, proteína e molho.', 'massas', 3, 'publicado', '{"introducao":"Três escolhas definem o prato: quanto de massa, se entra proteína e qual molho acompanha.","decisoes":[],"estabelecimentos":[{"id":"spoleto","nome":"Spoleto","grupo":"Montar no balcão","logo":null,"resumo":null,"ordem":1,"opcoes":[{"id":"spoleto-melhor","titulo":"Bambini ao molho de tomate com frango","descricao":"Massa comum, 100 g. Com refrigerante zero.","nivel":"melhor","energia":{"kcal":350,"mostrarKcal":true,"observacao":"Total do combo."},"detalhes":["Porção Bambini — 100 g de massa comum","Molho de tomate","Frango grelhado","Sem queijo extra","Refrigerante zero"],"tags":["massa","combo"]},{"id":"spoleto-boa","titulo":"Bambini ao branco ou bolonhesa com polpetone","descricao":"Massa comum, 100 g. Com refrigerante zero.","nivel":"boa","energia":{"kcal":460,"mostrarKcal":true,"observacao":"Total do combo."},"detalhes":["Porção Bambini — 100 g de massa comum","Molho branco ou bolonhesa","Polpetone de frango ou peru","Queijo moderado","Refrigerante zero"],"tags":["massa","combo"]},{"id":"spoleto-ocasional","titulo":"Tradicional aos quatro queijos com polpetone de carne","descricao":"Massa comum, 200 g. Com refrigerante zero.","nivel":"ocasional","energia":{"kcal":880,"mostrarKcal":true,"observacao":"Total do combo."},"detalhes":["Porção Tradicional — 200 g de massa comum","Molho quatro queijos","Polpetone de carne","Sem adicionais extras","Refrigerante zero"],"tags":["massa","combo"]}],"observacoes":[]},{"id":"restaurante-italiano","nome":"Restaurante italiano","grupo":"Restaurantes","logo":"data:image/svg+xml,<svg viewBox=''0 0 64 64'' xmlns=''http://www.w3.org/2000/svg''><ellipse cx=''32'' cy=''38'' rx=''29'' ry=''17'' fill=''%23EFEAE1''/><ellipse cx=''32'' cy=''36'' rx=''23'' ry=''13'' fill=''%23FBF8F3''/><path d=''M12 36c4-5 10-7 20-7s16 2 2