insert into conteudos (id, tipo, titulo, tema, resumo, icone, ordem, status, corpo, tags) values ('barzinho', 'comer_fora', 'Barzinho', null, 'O que pedir para beber, e o que costuma acompanhar.', 'taca', 7, 'publicado', '{"introducao":"As contas abaixo são para duas doses — é o mínimo que costuma acontecer numa saída. Os números são estimativa: bar não publica tabela, e a receita muda de casa para casa.","decisoes":[{"id":"com-drink","titulo":"Com drink","pergunta":"Duas doses, mais o que vem para beliscar.","observacoes":[],"opcoes":[{"id":"drink-melhor","titulo":"Caipirinha, vodka soda ou Moscow Mule","descricao":"Duas doses, com porção pequena de azeitonas ou castanhas.","nivel":"melhor","energia":{"kcal":450,"mostrarKcal":true,"observacao":"Estimativa do total."},"detalhes":["2 drinks — 360 kcal","Azeitonas ou castanhas, porção pequena — 90 kcal"],"tags":["barzinho","combo"]},{"id":"drink-boa","titulo":"Margarita, Cosmopolitan ou caipiroska","descricao":"Duas doses, com tábua de queijos pequena.","nivel":"boa","energia":{"kcal":700,"mostrarKcal":true,"observacao":"Estimativa do total."},"detalhes":["2 drinks — 500 kcal","Tábua de queijos pequena — 200 kcal"],"tags":["barzinho","combo"]},{"id":"drink-ocasional","titulo":"Piña colada, sex on the beach ou caipirinha de frutas","descricao":"Duas doses, com três bruschettas.","nivel":"ocasional","energia":{"kcal":950,"mostrarKcal":true,"observacao":"Estimativa do total."},"detalhes":["2 drinks — 800 kcal","Bruschettas, 3 unidades — 150 kcal"],"tags":["barzinho","combo"]}]},{"id":"com-chopp","titulo":"Com chopp","pergunta":"Duas doses, mais o que vem para beliscar.","observacoes":[],"opcoes":[{"id":"chopp-melhor","titulo":"Dois chopps pequenos","descricao":"300 ml cada, com porção pequena de azeitonas ou castanhas.","nivel":"melhor","energia":{"kcal":330,"mostrarKcal":true,"observacao":"Estimativa do total."},"detalhes":["2 chopps de 300 ml — 240 kcal","Azeitonas ou castanhas, porção pequena — 90 kcal"],"tags":["barzinho","combo"]},{"id":"chopp-boa","titulo":"Dois chopps médios","descricao":"500 ml cada, com tábua de queijos pequena.","nivel":"boa","energia":{"kcal":600,"mostrarKcal":true,"observacao":"Estimativa do total."},"detalhes":["2 chopps de 500 ml — 400 kcal","Tábua de queijos pequena — 200 kcal"],"tags":["barzinho","combo"]},{"id":"chopp-ocasional","titulo":"Dois chopps grandes","descricao":"700 ml cada, com três bruschettas.","nivel":"ocasional","energia":{"kcal":710,"mostrarKcal":true,"observacao":"Estimativa do total."},"detalhes":["2 chopps de 700 ml — 560 kcal","Bruschettas, 3 unidades — 150 kcal"],"tags":["barzinho","combo"]}]}],"estabelecimentos":[],"lembretes":[],"logo":null}'::jsonb, array['barzinho', 'bar', 'drink', 'chopp', 'cerveja', 'happy hour', 'alcool', 'petisco']::text[]) on conflict (id) do update set titulo = excluded.titulo, resumo = excluded.resumo, icone = excluded.icone, ordem = excluded.ordem, status = excluded.status, corpo = excluded.corpo, tags = excluded.tags, atualizado_em = now();
