-- Alimentos -------------------------------------------------------------------

-- Comer fora e guias ----------------------------------------------------------

-- O que saiu do ar, e os favoritos que apontavam para lá.
delete from favoritos where tipo = 'categoria' and ref_id in ('refeicao-livre', 'subway');
delete from favoritos where tipo = 'opcao' and ref_id in ('hamburguer:hamburguer-simples', 'hamburguer:hamburguer-denso', 'hamburguer:hamburguer-completa', 'japonesa:sunomono', 'japonesa:missoshiro', 'japonesa:edamame', 'japonesa:sashimi', 'japonesa:niguiri', 'japonesa:temaki-simples', 'japonesa:fritos', 'japonesa:molhos-cremosos', 'massas:massa-camarao', 'massas:massa-frango', 'massas:massa-lasanha', 'pizza:pizza-fina', 'pizza:pizza-grossa', 'acai:acai-500', 'acai:acai-300', 'subway:subway-melhor', 'subway:subway-boa', 'subway:subway-ocasional');
delete from conteudos where id in ('refeicao-livre', 'subway');

-- Configurações ---------------------------------------------------------------

-- Conferência: deve listar um total por grupo, e nenhum alimento com porção
-- e "quantidade livre" ao mesmo tempo.
select g.nome as grupo,
       count(*) as alimentos,
       count(a.porcao_quantidade) as com_porcao,
       count(*) filter (where a.quantidade_livre) as livres
  from alimentos a
  join grupos_alimentares g on g.id = a.grupo_id
 group by g.nome, g.ordem
 order by g.ordem;

-- E as categorias de Comer fora, com quantas casas cada uma tem.
select titulo,
       status,
       jsonb_array_length(coalesce(corpo -> 'estabelecimentos', '[]'::jsonb)) as casas
  from conteudos
 where tipo = 'comer_fora'
 order by ordem;
